-- Prepared rollback only; NOT EXECUTED. Public knowledge, no customer records or credentials.
-- Use the existing approved owner connection to the assistant-only velani_ai database.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext(current_database()), hashtext(current_schema() || ':velani-seed'));
DO $guard$ BEGIN IF (SELECT count(*) FROM knowledge_documents) <> 16 OR EXISTS (SELECT 1 FROM jsonb_to_recordset('[{"id":"nevora-availability-en","content_hash":"16fce3ea1e794997f299e8534bd857b5fdf6ca458d843ce528c3840290e34e87","updated_at":"2026-11-05 14:24:08.315592+00","status":"published"},{"id":"nevora-availability-es","content_hash":"197c73f58143b7890bc55571ec2a0edaff5d209ddf0f96674df0e340ccf808ee","updated_at":"2026-11-05 14:24:08.321682+00","status":"published"},{"id":"nevora-overview-en","content_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","updated_at":"2026-11-05 14:24:08.323212+00","status":"published"},{"id":"nevora-overview-es","content_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","updated_at":"2026-11-05 14:24:08.325336+00","status":"published"},{"id":"nevora-payroll-en","content_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","updated_at":"2026-11-05 14:24:08.326774+00","status":"published"},{"id":"nevora-payroll-es","content_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","updated_at":"2026-11-05 14:24:08.328813+00","status":"published"},{"id":"nevora-rondo-en","content_hash":"7b61c2ec52be47d576da9b47d21721bfd2e9b376ec3b1a02c3d4e708fd82999e","updated_at":"2026-11-05 14:24:08.330861+00","status":"published"},{"id":"nevora-rondo-es","content_hash":"0c1bb85fad0d14455e04c89274074cf2bd9b414966df1e679dd6a20015f80635","updated_at":"2026-11-05 14:24:08.332377+00","status":"published"},{"id":"nevora-support-en","content_hash":"93d33a4cef160c41b2dba9bc9baaa6f7ef994248027b14d74b582aab9e95924c","updated_at":"2026-11-05 14:24:08.333887+00","status":"published"},{"id":"nevora-support-es","content_hash":"52d70dcc443424ae8d94cc0cd6d958163568593f118c4ee764a4c6a00b418c88","updated_at":"2026-11-05 14:24:08.335381+00","status":"published"},{"id":"nevora-time-clock-en","content_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","updated_at":"2026-11-05 14:24:08.337402+00","status":"published"},{"id":"nevora-time-clock-es","content_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","updated_at":"2026-11-05 14:24:08.338752+00","status":"published"},{"id":"velani-enquiries-en","content_hash":"9ba452b9cdaefc660ccc734fa60d858518686fc214dc26de09b92d8569f19faa","updated_at":"2026-11-05 14:24:08.340146+00","status":"published"},{"id":"velani-enquiries-es","content_hash":"7ba7e5484f1e35f2a55affde0c9577b7f5cf7becb0471ace69082b573dee2f2c","updated_at":"2026-11-05 14:24:08.341644+00","status":"published"},{"id":"velani-relay-en","content_hash":"d3a677ea1ac57f316d74d5d0ac00dd1b8fd37b3389a29cfd14004ff6fedc1a2b","updated_at":"2026-11-05 14:24:08.343032+00","status":"published"},{"id":"velani-relay-es","content_hash":"ef443527e9ba5869382b9a13a2bd2a2b78d4bd0afa81e14cc12f49233d32de2b","updated_at":"2026-11-05 14:24:08.344365+00","status":"published"}]'::jsonb) AS expected(id text,content_hash text,updated_at timestamptz,status text) FULL JOIN knowledge_documents actual USING (id) WHERE actual.id IS NULL OR expected.id IS NULL OR actual.content_hash IS DISTINCT FROM expected.content_hash OR actual.updated_at IS DISTINCT FROM expected.updated_at OR actual.status IS DISTINCT FROM expected.status) THEN RAISE EXCEPTION 'Knowledge changed since refresh; do not overwrite subsequent work'; END IF; END $guard$;
INSERT INTO knowledge_documents (id, title, url, content, locale, reviewed_at, valid_until, status, is_core, managed_by, content_hash, embedding, updated_at)
SELECT id, title, url, content, locale, reviewed_at, valid_until, status, is_core, managed_by, content_hash, embedding::vector, updated_at FROM jsonb_to_recordset('[{"id":"nevora-availability-en","title":"Trial, setup, pricing and end-of-trial choices","url":"https://www.thevelani.com/?view=velani-plans","content":"Published plans advertise a free 30-day NEVORA trial, beginning when the team sets up the workplace, for up to 30 employees. No card is required and there is no automatic charge on day 30. Larger teams require a quote; do not assume standard trial eligibility or invent exceptions. After the trial there is one price per business, quoted for its team and locations. No numeric public rate is established: do not invent per-employee rates or binding totals. The team must confirm setup timing and terms; this assistant cannot activate a trial. On day 30 the business may continue by quote or export schedules, timecards and pay statements. The published plan says that if the business does not continue, its workplace and all data, including timecards and pay statements, are deleted within 3 days; export first if records are needed. This is a published policy, not proof of a tested deletion job or a tool this chat can execute. A quote enquiry is nonbinding. Use existing team-size and location context without asking again.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"7ee42a9e9d99d959395c66cc0c1cb35b321b4d849d9e6dca313396db7202cff9","embedding":null,"updated_at":"2026-11-05 02:19:14.272482+00"},{"id":"nevora-availability-es","title":"Prueba, configuración, precios y fin de la prueba","url":"https://www.thevelani.com/?view=velani-plans","content":"Los planes públicos anuncian una prueba gratuita de NEVORA por 30 días desde que el equipo configura el espacio de trabajo, para hasta 30 empleados. No se requiere tarjeta ni hay cobro automático el día 30. Los equipos más grandes requieren cotización; no se debe asumir que reciben la prueba estándar ni inventar excepciones. Después hay un precio por empresa, cotizado según equipo y ubicaciones. No hay tarifa numérica pública: no se deben inventar precios por empleado ni totales vinculantes. El equipo confirma plazo y condiciones; este asistente no activa pruebas. El día 30 se puede continuar por cotización o exportar horarios, registros y comprobantes. El plan publicado indica que, si no se continúa, se elimina el espacio y todos sus datos, incluidos registros y comprobantes, dentro de 3 días; conviene exportar antes los registros necesarios. Es una política publicada, no evidencia de una tarea de eliminación probada ni una herramienta que pueda ejecutar este chat. Consultar una cotización no obliga a comprar. Hay que aprovechar empleados y ubicaciones ya compartidos.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"b8ec9440c4a4e701d60e429dd3c1629056a4007c2d4a9bd5fb1c88d833ba540b","embedding":null,"updated_at":"2026-11-05 02:19:14.278114+00"},{"id":"nevora-overview-en","title":"NEVORA: product purpose and team workflows","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA is Velani''s workforce product for shift teams. Its published product page now advertises availability with workplace setup by the team, not instant self-service signup by this chat. Managers plan shifts and approve hours on the web. Employees view shifts, respond to swaps and request time off on phones. Approved hours feed payroll calculations and pay statements. It works on web, phones and shared tablets, with English or Spanish chosen by each person. Published capabilities do not establish specific integrations, automated legal compliance, guaranteed savings or same-day setup. The website assistant provides advice, not authenticated employer-account operations. The separate trial article contains the current commercial limits.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"aae3742465a1b57fa5a1da299eb5d948b8c5adcef191352d6191029945aff468","embedding":null,"updated_at":"2026-11-05 02:19:14.278734+00"},{"id":"nevora-overview-es","title":"NEVORA: propósito del producto y trabajo por turnos","url":"https://www.thevelani.com/pages/nevora","content":"NEVORA es el producto de Velani para equipos por turnos. Su página pública ahora anuncia disponibilidad con configuración por el equipo, no registro instantáneo mediante este chat. Los administradores organizan turnos y aprueban horas en la web. Los empleados consultan turnos, responden a intercambios y solicitan tiempo libre desde teléfonos. Las horas aprobadas alimentan el cálculo de nómina y los comprobantes. Funciona en web, teléfonos y tabletas compartidas, con inglés o español elegido por cada persona. Estas funciones no establecen integraciones específicas, cumplimiento legal automático, ahorros garantizados ni configuración el mismo día. El asistente del sitio orienta, no opera cuentas de empresas. El artículo de prueba contiene los límites comerciales actuales.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"e4c10340de70fb653f3f0c45cbb943adcec6e28b9c26976a52cd390493a39d5e","embedding":null,"updated_at":"2026-11-05 02:19:14.279238+00"},{"id":"nevora-payroll-en","title":"Payroll calculations and employer responsibilities","url":"https://www.thevelani.com/pages/nevora","content":"The described NEVORA payroll workflow calculates payroll from approved hours. A manager reviews the calculations and publishes employee pay statements. NEVORA does not pay employees and does not file payroll taxes; those tasks remain the employer''s responsibility. Do not describe the product as a payroll-payment service, direct-deposit service, tax-filing service or replacement for the employer''s payroll provider unless newly reviewed official documentation expressly confirms that capability. There is no verified list here of supported payroll integrations, export formats, overtime rules, tax jurisdictions or deductions. Ask about the employer''s current approval and payroll process when helpful, and refer detailed compatibility or legal-compliance questions to the team. The website assistant cannot read, calculate from, modify or publish a real employee''s payroll records.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"21cba76793bb38151632f47693029ccf8dc67bb942cf657dfa003a8fa6042765","embedding":null,"updated_at":"2026-11-05 02:19:14.279865+00"},{"id":"nevora-payroll-es","title":"Cálculo de nómina y responsabilidades del empleador","url":"https://www.thevelani.com/pages/nevora","content":"El flujo de nómina descrito de NEVORA calcula la nómina a partir de horas aprobadas. Un administrador revisa los cálculos y publica los comprobantes de pago de los empleados. NEVORA no paga a los empleados ni presenta impuestos de nómina; esas tareas siguen siendo responsabilidad del empleador. No se debe presentar el producto como servicio de pago, depósito directo o presentación de impuestos, ni como sustituto del proveedor de nómina, salvo que nueva documentación oficial revisada confirme expresamente esa función. Aquí no hay una lista verificada de integraciones de nómina, formatos de exportación, reglas de horas extras, jurisdicciones fiscales o deducciones. Cuando ayude, conviene preguntar cómo se aprueban y procesan las horas actualmente y remitir dudas específicas de compatibilidad o cumplimiento al equipo. El asistente no puede consultar, modificar ni publicar la nómina real de un trabajador.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"204051131b2ebb40541097feb1a049568f182d4cd5d8616466e494fd20ba0311","embedding":null,"updated_at":"2026-11-05 02:19:14.280991+00"},{"id":"nevora-rondo-en","title":"Rondo: website advice and planned in-app assistance","url":"https://www.thevelani.com/pages/nevora","content":"Rondo is the name of NEVORA''s AI assistant. The public product page labels the in-app owner assistant as in development. Its planned experience includes morning briefings, identifying possible cover, reviewing timecards before payday and remembering owner priorities, with owner approval before changes. The example uses fictional people, not evidence of live capabilities. Do not promise these planned functions as available today. This website Rondo is a product adviser: it explains published information, helps reason through workflows and offers a voluntary contact form. It has no authenticated workforce access and cannot read attendance, rank actual employees, remember priorities across accounts, prepare real schedule changes or approve actions. Sharing a name does not grant planned in-app tools. Explain this distinction naturally when asked about Rondo or operational actions.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"5c4c5d22f75a3d1be19f0dbdca32578f01c4adeaea66fe1839b385b56bc7ef45","embedding":null,"updated_at":"2026-11-05 02:19:14.281425+00"},{"id":"nevora-rondo-es","title":"Rondo: orientación web y asistencia prevista en la aplicación","url":"https://www.thevelani.com/pages/nevora","content":"Rondo es el nombre del asistente de IA de NEVORA. La página pública marca el asistente para propietarios dentro de la aplicación como en desarrollo. Su experiencia prevista incluye resúmenes de la mañana, posibles sustitutos, revisión de registros antes de la nómina y memoria de prioridades, con aprobación del propietario antes de cambios. El ejemplo usa personas ficticias y no demuestra funciones activas. No se deben prometer estas funciones como disponibles hoy. Este Rondo del sitio orienta sobre el producto: explica información publicada, ayuda a razonar sobre procesos y ofrece contacto voluntario. No tiene acceso autenticado a personal ni puede leer asistencia, clasificar empleados reales, recordar prioridades entre cuentas, preparar cambios reales ni aprobar acciones. Compartir el nombre no concede las herramientas previstas. Hay que explicar esta diferencia cuando pregunten por Rondo o acciones operativas.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"1800ba771b97619f13f3488a74c9b660e8bf58fca6af5bddc78a41d77d1473bc","embedding":null,"updated_at":"2026-11-05 02:19:14.281948+00"},{"id":"nevora-support-en","title":"Employee account help and privacy boundaries","url":"https://www.thevelani.com/pages/nevora-support","content":"NEVORA employee accounts come from the employer. For access problems or questions about a personal schedule, timecard or pay statement, the employee should contact their manager or employer and use the official NEVORA support route when needed. Velani publishes support@thevelani.com. The website product assistant has no authenticated access to employer accounts, employee directories, wages, PINs, passwords, schedules or payroll. It cannot reset credentials, edit time punches, approve leave or delete an account. Do not ask a visitor to paste credentials, government identifiers, financial details or employee records into this chat. The official product privacy and account-deletion pages are https://www.thevelani.com/pages/nevora-privacy and https://www.thevelani.com/pages/nevora-account-deletion. The current product page publishes United States, Northern Virginia as the data location, encrypted connections and role-based access. These are published product statements, not independent security verification. SOC 2 certification, HIPAA or labor-law compliance, detailed backup controls and contractual guarantees are not established here and need supporting evidence from the team. Do not infer certifications or universal compliance from the stated location or controls.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"93d33a4cef160c41b2dba9bc9baaa6f7ef994248027b14d74b582aab9e95924c","embedding":null,"updated_at":"2026-11-05 02:19:14.282582+00"},{"id":"nevora-support-es","title":"Ayuda con cuentas de empleados y límites de privacidad","url":"https://www.thevelani.com/pages/nevora-support","content":"El empleador proporciona las cuentas de empleados de NEVORA. Si una persona necesita acceso o ayuda con su horario, registro de horas o comprobante de pago, debe acudir a su administrador o empleador y, cuando sea necesario, al soporte oficial de NEVORA. Velani publica support@thevelani.com. El asistente comercial del sitio no tiene acceso autenticado a cuentas de empresas, directorios, salarios, PIN, contraseñas, horarios ni nóminas. No puede restablecer credenciales, modificar fichajes, aprobar permisos ni eliminar cuentas. No se deben pedir contraseñas, documentos de identidad, datos financieros o expedientes de empleados en este chat. Las páginas oficiales de privacidad y eliminación de cuenta son https://www.thevelani.com/pages/nevora-privacy y https://www.thevelani.com/pages/nevora-account-deletion. La página actual publica Estados Unidos, Virginia del Norte como ubicación de los datos, conexiones cifradas y acceso por roles. Son declaraciones publicadas del producto, no una auditoría independiente de seguridad. Aquí no se establecen certificación SOC 2, cumplimiento HIPAA o laboral, controles detallados de respaldo ni garantías contractuales; el equipo debe aportar evidencia. La ubicación o estos controles no demuestran certificaciones ni cumplimiento universal.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":true,"managed_by":"seed","content_hash":"52d70dcc443424ae8d94cc0cd6d958163568593f118c4ee764a4c6a00b418c88","embedding":null,"updated_at":"2026-11-05 02:19:14.283225+00"},{"id":"nevora-time-clock-en","title":"Shared PIN time clock, languages and demonstration limits","url":"https://www.thevelani.com/pages/nevora","content":"The published NEVORA page offers a public sample time clock. Visitors may enter any four sample digits; the screen clears for the next person. The page says nothing entered in this demonstration is saved or sent. It is a fictional workplace, not real attendance, payroll or account access. Never enter a real employee PIN in the sample. The actual product uses a four-digit PIN on a shared-tablet clock, separate from the portal password. English and Spanish are available, chosen by each person. Managers review real attendance in the authenticated workplace. This assistant cannot clock someone in, generate PINs or create accounts. A requested demonstration may use show_demo with this source, without claiming it has already been opened.","locale":"en","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":false,"managed_by":"seed","content_hash":"53c6b6cf9503107ea4473a315b873c1993ca48ce9e1914ae3b043f8d51a401eb","embedding":null,"updated_at":"2026-11-05 02:19:14.283886+00"},{"id":"nevora-time-clock-es","title":"Reloj compartido con PIN, idiomas y límites de la demostración","url":"https://www.thevelani.com/pages/nevora","content":"La página pública de NEVORA ofrece un reloj de muestra. Se pueden escribir cuatro dígitos de ejemplo y la pantalla se limpia para la siguiente persona. La página indica que nada de lo introducido se guarda ni se envía. Es un espacio ficticio, no asistencia real, nómina ni acceso a cuentas. No se debe usar un PIN real de empleado. El producto utiliza un PIN de cuatro dígitos en una tableta compartida, separado de la contraseña del portal. Cada persona elige inglés o español. Los administradores revisan asistencia real en su espacio autenticado. Este asistente no ficha, genera PIN ni crea cuentas. Si se solicita una demostración, puede usarse show_demo con esta fuente, sin afirmar que ya se abrió.","locale":"es","reviewed_at":"2026-11-04 00:00:00+00","valid_until":"2026-12-04 23:59:59.999+00","status":"published","is_core":false,"managed_by":"seed","content_hash":"552be9b4e42974c7499ec30e6e4974ed269ffa85e2f4a4fa1ed1e3ea89d8d82b","embedding":null,"updated_at":"2026-11-05 02:19:14.284382+00"},{"id":"velani-enquiries-en","title":"Velani, custom development and commercial enquiries","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani is a brand of VELANI LLC. Alongside NEVORA, its site describes custom web and mobile applications, business systems and integrations; custom project scope and pricing require a discussion with the team. Custom-development information is at https://www.thevelani.com/pages/custom-development and enquiries can use https://www.thevelani.com/pages/contact?interest=custom-software. NEVORA enquiries can use https://www.thevelani.com/pages/contact?interest=nevora. A helpful assistant answers the visitor''s product question before suggesting a quote or follow-up. For this assistant''s lead workflow, contact details are submitted through an explicit form with consent. Mentioning an email address in chat does not mean a lead was saved, an email was sent or a meeting was booked. The language model cannot perform these actions. Do not claim completion without the application confirming a successful submission. Do not invent a booking URL, response-time promise or named sales representative.","locale":"en","reviewed_at":"2026-11-02 00:00:00+00","valid_until":"2026-12-02 23:59:59.999+00","status":"published","is_core":false,"managed_by":"seed","content_hash":"f6f84f94365f42075fb1b0b5bf68bddb9c65b4c77b6a4744cd4a8cee46c37733","embedding":null,"updated_at":"2026-11-05 02:19:14.284894+00"},{"id":"velani-enquiries-es","title":"Velani, desarrollo a medida y consultas comerciales","url":"https://www.thevelani.com/pages/contact?interest=nevora","content":"Velani es una marca de VELANI LLC. Además de NEVORA, su sitio describe aplicaciones web y móviles a medida, sistemas empresariales e integraciones; el alcance y precio de un proyecto se acuerdan con el equipo. La información de desarrollo a medida está en https://www.thevelani.com/pages/custom-development y las consultas pueden dirigirse a https://www.thevelani.com/pages/contact?interest=custom-software. Para NEVORA, la ruta es https://www.thevelani.com/pages/contact?interest=nevora. El asistente debe resolver primero la pregunta del visitante y después, si resulta útil, sugerir una cotización o seguimiento. En el flujo de este asistente, los datos de contacto se envían mediante un formulario explícito con consentimiento. Escribir un correo en el chat no significa que se haya guardado una consulta, enviado un mensaje o reservado una reunión. El modelo no realiza esas acciones ni debe afirmar que terminaron sin confirmación de la aplicación. No se deben inventar enlaces de reserva, plazos de respuesta ni representantes.","locale":"es","reviewed_at":"2026-11-02 00:00:00+00","valid_until":"2026-12-02 23:59:59.999+00","status":"published","is_core":false,"managed_by":"seed","content_hash":"0fcc9f830f529715a3db0ea227e34dd12c493577afe20cbf6356f8ec7e9af81e","embedding":null,"updated_at":"2026-11-05 02:19:14.28547+00"}]'::jsonb) AS prior(id text, title text, url text, content text, locale text, reviewed_at timestamptz, valid_until timestamptz, status text, is_core boolean, managed_by text, content_hash text, embedding text, updated_at timestamptz)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, url = EXCLUDED.url, content = EXCLUDED.content, locale = EXCLUDED.locale, reviewed_at = EXCLUDED.reviewed_at, valid_until = EXCLUDED.valid_until, status = EXCLUDED.status, is_core = EXCLUDED.is_core, managed_by = EXCLUDED.managed_by, content_hash = EXCLUDED.content_hash, embedding = EXCLUDED.embedding, updated_at = EXCLUDED.updated_at;
UPDATE knowledge_documents SET status='archived',updated_at=clock_timestamp() WHERE id IN ('velani-relay-en','velani-relay-es') AND managed_by='seed';
COMMIT;
